const $=s=>document.querySelector(s);let rows=[],generated=[],generatedDays=0,pending=null;
function status(s){$('#status').textContent=s;}
async function api(action,data={}){const r=await fetch('/api/license',{method:'POST',headers:{'Content-Type':'application/json'},credentials:'same-origin',body:JSON.stringify({action,...data})});const b=await r.json();if(!r.ok||!b.ok){if(r.status===401){$('#login').hidden=false;$('#dashboard').hidden=true;$('#logout').hidden=true;}throw new Error(b.message||'Request failed');}return b;}
function time(s){return s?new Date(s).toISOString().slice(0,16).replace('T',' '):'—';}
function state(l){return l.revoked?'Revoked':l.expires_at&&Date.parse(l.expires_at)<=Date.now()?'Expired':!l.activated_at?'Unused':l.device_hash?'Active':'Awaiting new device';}
function render(){const q=$('#filter').value.toLowerCase();$('#licenses').replaceChildren(...rows.filter(l=>[l.label,l.id,state(l)].join(' ').toLowerCase().includes(q)).map(l=>{const tr=document.createElement('tr');for(const text of [l.label||'Unlabelled',l.duration_days?l.duration_days+' days':'Forever',state(l),time(l.activated_at),l.duration_days===0?'Forever':time(l.expires_at),l.device_hash?'Bound · '+l.device_hash.slice(0,8):'Not bound']){const td=document.createElement('td');td.textContent=text;tr.append(td);}const small=document.createElement('small');small.textContent=l.id;tr.firstChild.append(small);const td=document.createElement('td');for(const [action,label] of [[l.revoked?'restore':'revoke',l.revoked?'Restore':'Revoke'],['reset_device','Reset PC']]){const b=document.createElement('button');b.textContent=label;b.onclick=()=>confirmAction(l,action);td.append(b);}tr.append(td);return tr;}));$('#totals').textContent=`${rows.length} licenses · ${rows.filter(l=>state(l)==='Unused').length} unused · ${rows.filter(l=>state(l)==='Active').length} active`;}
async function refresh(){try{const b=await api('list');rows=b.licenses;$('#login').hidden=true;$('#dashboard').hidden=false;$('#logout').hidden=false;render();$('#audit').replaceChildren(...b.audit.map(e=>{const p=document.createElement('div');p.textContent=`${time(e.created_at)} UTC · ${e.action} · ${e.license_id||'batch'}`;return p;}));status('Connected. License data loaded.');}catch(e){status(e.message);}}
$('#login-form').onsubmit=async e=>{e.preventDefault();const b=e.submitter;b.disabled=true;try{await api('login',{secret:$('#secret').value});$('#secret').value='';await refresh();}catch(x){status(x.message);}finally{b.disabled=false;}};
$('#logout').onclick=async()=>{await api('logout');location.reload();};$('#refresh').onclick=refresh;$('#filter').oninput=render;
$('#create-form').onsubmit=async e=>{e.preventDefault();if(generated.length){status('Download or clear the previous generated batch first.');return;}e.submitter.disabled=true;try{const b=await api('create',{days:Number($('#days').value),count:Number($('#count').value),label:$('#label').value});generated=b.keys;generatedDays=b.days;$('#key-output').value=generated.join('\n');$('#new-keys').hidden=false;await refresh();status('Keys generated. Save the private list now.');}catch(x){status(x.message);}finally{e.submitter.disabled=false;}};
$('#download').onclick=()=>{const csv='Key,Days\r\n'+generated.map(k=>k+','+(generatedDays||'Forever')).join('\r\n');const u=URL.createObjectURL(new Blob([csv],{type:'text/csv;charset=utf-8'}));const a=document.createElement('a');a.href=u;a.download=`AQx-${generatedDays||'permanent'}-day-keys-${Date.now()}.csv`;a.click();setTimeout(()=>URL.revokeObjectURL(u),1000);};
$('#copy').onclick=async()=>{try{await navigator.clipboard.writeText(generated.join('\n'));status('Keys copied.');}catch{status('Select and copy the displayed keys manually.');}};$('#clear-export').onclick=()=>{generated=[];$('#key-output').value='';$('#new-keys').hidden=true;};
function confirmAction(l,action){pending={id:l.id,action};$('#confirm-title').textContent=action==='reset_device'?'Reset device binding?':action==='revoke'?'Revoke license?':'Restore license?';$('#confirm-text').textContent=action==='reset_device'?'The next PC to use this key will be bound to it. The original activation time and expiry remain unchanged.':action==='revoke'?'Future online launcher checks will reject this key. You can restore it later.':'This removes the revocation. An expired key will still be expired.';$('#confirmation').showModal();}
$('#cancel-action').onclick=()=>{$('#confirmation').close();pending=null;};$('#confirm-action').onclick=async()=>{if(!pending)return;$('#confirm-action').disabled=true;try{await api(pending.action,{id:pending.id});$('#confirmation').close();pending=null;await refresh();}catch(e){status(e.message);}finally{$('#confirm-action').disabled=false;}};
refresh();
